240: impl Selector {
241:     fn indices(
242:         &self,
243:         first_record: &csv::ByteRecord,
244:         use_names: bool,
245:     ) -> Result<Vec<usize>, String> {
246:         match *self {
247:             Selector::One(ref sel) => {
248:                 sel.index(first_record, use_names).map(|i| vec![i])
249:             }
250:             Selector::Range(ref sel1, ref sel2) => {
251:                 let i1 = sel1.index(first_record, use_names)?;
252:                 let i2 = sel2.index(first_record, use_names)?;
253:                 Ok(match i1.cmp(&i2) {
254:                     Ordering::Equal => vec!(i1),
255:                     Ordering::Less => (i1..(i2 + 1)).collect(),
256:                     Ordering::Greater => {
257:                         let mut inds = vec![];
258:                         let mut i = i1 + 1;
259:                         while i > i2 {
260:                             i -= 1;
261:                             inds.push(i);
262:                         }
263:                         inds
264:                     }
265:                 })
266:             }
267:         }
268:     }
269: }
